function $(s){return document.querySelector(s)}function esc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&gt;","'":"&#39;","\"":"&quot;"}[c]))}function key(d){d=new Date(d);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}function apiDate(d){return key(d).replaceAll("-","")}function qty(v){return Number(v||0).toLocaleString("ko-KR",{maximumFractionDigits:1})}function won(v){return `₩${Math.round(v||0).toLocaleString("ko-KR")}`}function item(id){return state.items.find(x=>x.id===id)}function low(x){return x.stock!==""&&Number(x.stock)<=Number(x.threshold)}function step(x){return x?.id==="egg"?1:x?.unit==="kg"?.1:1}function today(){return key(new Date())}function loadMarketCache(){return{}}function saveMarketCache(){}
