function setStock(id,value){const x=item(id),next=value===""?"":Math.max(0,Math.round(Number(value)*10)/10);if(String(x.stock)===String(next))return;if(!(id in state.draftBefore))state.draftBefore[id]=x.stock;x.stock=next;x.updatedAt=new Date().toISOString();save();render()}function commitStock(){const changes=Object.entries(state.draftBefore);if(!changes.length)return message("확정할 재고 변경이 없어요.");changes.forEach(([id,before])=>{const x=item(id),after=x.stock;if(String(before)===String(after))return;const d=(Number(after)||0)-(Number(before)||0);log("stock",x,`재고 확정 · ${d>0?"+":""}${qty(d)}${x.unit}`)});state.draftBefore={};save();render();message("재고 변경을 이력에 확정했어요.")}
