function eventLabel(h){return h.type==="order"?"발주":h.type==="received"?"입고":h.type==="stock"?"재고":h.type==="close"?"마감":"기록"}function calendar(){const y=month.getFullYear(),m=month.getMonth(),start=new Date(y,m,1).getDay(),last=new Date(y,m+1,0).getDate(),week=["일","월","화","수","목","금","토"].map(x=>`<span class="weekday">${x}</span>`).join(""),days=Array.from({length:last},(_,n)=>{const d=n+1,k=`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`,ev=state.history.filter(h=>key(h.at)===k),labels=[...new Set(ev.map(eventLabel))];return `<button class="calendar-day ${ev.length?"has":""} ${k===today()?"today":""}" data-history-date="${k}"><b>${d}</b>${labels.slice(0,2).map(v=>`<small class="${v==="입고"?"receipt":""}">${v}</small>`).join("")}${labels.length>2?"<small>외 기록</small>":""}</button>`}).join("");$("#historyView").innerHTML=`<div class="section-head"><div><h2>재고·발주 이력</h2><p>날짜를 누르면 세부 내역을 크게 볼 수 있어요.</p></div></div><div class="card month-bar"><button data-month="-1">‹</button><strong>${y}년 ${m+1}월</strong><button data-month="1">›</button></div><section class="history-calendar">${week}${Array.from({length:start},()=>"<span></span>").join("")}${days}</section><p class="history-help">달력 안에 발주·입고·재고·마감 기록이 표시됩니다.</p>`}
function historyModal(k){const ev=state.history.filter(h=>key(h.at)===k);$("#modalRoot").innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-top"><div><h3>${k} 기록</h3><p class="history-help">${ev.length}건</p></div><button class="close" data-close-modal>×</button></div>${ev.length?ev.map(h=>`<article class="event-row"><time>${new Date(h.at).toLocaleTimeString("ko-KR",{hour:"2-digit",minute:"2-digit"})} · ${eventLabel(h)}</time><strong>${esc(h.itemName)}</strong> · ${esc(h.text)}</article>`).join(""):'<p class="history-help">이 날짜의 기록이 없습니다.</p>'}</section></div>`}
function settings(){if(settingsPage==="menu"){$("#settingsView").innerHTML=`<div class="section-head"><div><h2>설정</h2><p>설정할 항목을 선택하세요.</p></div></div><section class="setting-menu"><button data-settings-page="items"><span><strong>품목·발주 설정</strong><small>기준재고, 기본 발주량, 단가를 수정합니다.</small></span><b>›</b></button><button data-settings-page="backup"><span><strong>데이터 백업·복원</strong><small>재고·발주·이력·설정을 파일로 보관합니다.</small></span><b>›</b></button></section>`;return}if(settingsPage==="items"){$("#settingsView").innerHTML=`<div class="section-head"><div><h2>품목·발주 설정</h2><p>기준재고와 기본 발주량을 수정합니다.</p></div><button class="secondary" data-settings-page="menu">뒤로</button></div><section class="card setting-list">${state.items.map(x=>`<div class="setting-row"><div><h3>${x.name}</h3><p>기준 ${qty(x.threshold)}${x.unit} · 기본 발주 ${qty(x.orderAmount)}${x.unit}</p></div><input data-setting="${x.id}" data-key="orderAmount" type="number" step="${step(x)}" value="${x.orderAmount}"></div>`).join("")}</section>`;return}$("#settingsView").innerHTML=`<div class="section-head"><div><h2>데이터 백업·복원</h2><p>복원하면 이 기기의 현재 데이터가 바뀝니다.</p></div><button class="secondary" data-settings-page="menu">뒤로</button></div><section class="card inbound-panel"><strong>안전하게 보관하세요</strong><p>재고, 발주, 이력, 품목 설정을 JSON 파일로 저장합니다.</p><div class="backup-actions"><button class="secondary" id="backup">백업 저장</button><button class="primary" id="restore">복원하기</button></div><input id="restoreFile" type="file" accept="application/json" hidden></section>`}
function download(){const b=new Blob([JSON.stringify(state,null,2)],{type:"application/json"}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download=`veggi-order-${today()}.json`;a.click();URL.revokeObjectURL(u);message("백업 파일을 저장했어요.")}function restore(f){const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!Array.isArray(d.items))throw 0;state={items:normalize(d.items),history:d.history||[],order:d.order||d.orderDraft||{stage:"ready",delivery:key(Date.now()+864e5),lines:{}},market:{period:d.market?.period||d.market?.range||7,order:d.market?.order||base.map(x=>x.id),grades:d.market?.grades||{}},draftBefore:{}};save();render();message("백업을 복원했어요.")}catch{message("올바른 백업 파일이 아닙니다.")}};r.readAsText(f)}
window.addEventListener("veggi-market-history-ready",()=>{if(current==="marketView")market()});function render(){inventory();orders();market();calendar();settings();document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x.id===current));document.querySelectorAll(".bottom-nav button").forEach(x=>x.classList.toggle("active",x.dataset.view===current));$("#todayLabel").textContent=new Date().toLocaleDateString("ko-KR",{month:"long",day:"numeric",weekday:"short"})}
document.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(b.dataset.view){current=b.dataset.view;render();window.scrollTo({top:0,behavior:"smooth"})}if(b.dataset.stockStep){const x=item(b.dataset.stockStep);setStock(x.id,Math.max(0,(Number(x.stock)||0)+(b.dataset.dir==="+"?step(x):-step(x))))}if(b.dataset.stockValue)setStock(b.dataset.stockValue,b.dataset.value);if(b.id==="commitStock")commitStock();if(b.id==="dailyClose"){if(Object.keys(state.draftBefore).length)return message("재고 변경을 먼저 최종 확정해 주세요.");log("close",null,`일일 재고 마감 · ${state.items.filter(x=>x.stock!=="").length}개 품목 확인`);save();render();message("오늘 재고 마감을 완료했어요.")}if(b.id==="orderAction")state.order.stage==="sent"?receiveOrder():sendOrder();if(b.id==="copyOrder")navigator.clipboard?.writeText(orderText()).then(()=>message("발주 내용을 복사했어요."));if(b.dataset.period){state.market.period=Number(b.dataset.period);state.market.selected={};save();market()}if(b.dataset.marketPoint){state.market.selected??={};state.market.selected[b.dataset.marketPoint]=Number(b.dataset.index);save();market()}if(b.dataset.moveMarket){const a=state.market.order,i=a.indexOf(b.dataset.moveMarket),j=i+(b.dataset.dir==="+"?1:-1);if(a[j]){[a[i],a[j]]=[a[j],a[i]];save();market()}}if(b.dataset.month){month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1);calendar()}if(b.dataset.historyDate)historyModal(b.dataset.historyDate);if(b.dataset.closeModal)$("#modalRoot").innerHTML="";if(b.dataset.settingsPage){settingsPage=b.dataset.settingsPage;settings()}if(b.id==="backup")download();if(b.id==="restore")$("#restoreFile")?.click()});
document.addEventListener("click",e=>{if(e.target.closest("#refreshMarket"))refreshLiveMarket(true)});
document.addEventListener("click",e=>{const p=e.target.closest("[data-market-point]");if(!p)return;state.market.selected??={};state.market.selected[p.dataset.marketPoint]=Number(p.dataset.index);save();renderMarketCard(p.dataset.marketPoint)});
document.addEventListener("click",e=>{const s=e.target.closest("[data-chart-surface]");if(!s)return;const box=s.ownerSVGElement.getBoundingClientRect(),viewWidth=350,left=Number(s.dataset.left),width=Number(s.dataset.width),x=(e.clientX-box.left)/box.width*viewWidth,index=Math.max(0,Math.min(Number(s.dataset.days)-1,Math.round((x-left)/width*(Number(s.dataset.days)-1))));state.market.selected??={};state.market.selected[s.dataset.chartSurface]=index;save();renderMarketCard(s.dataset.chartSurface)});
document.addEventListener("click",e=>{if(e.target.closest("[data-close-modal]"))$("#modalRoot").innerHTML=""});
document.addEventListener("click",e=>{const b=e.target.closest("[data-order-value]");if(!b)return;state.order.lines[b.dataset.orderValue]=Math.max(0,Math.round(Number(b.dataset.value)*10)/10);save();orders()});
document.addEventListener("change",e=>{if(e.target.matches("[data-stock]"))setStock(e.target.dataset.stock,e.target.value);if(e.target.matches("[data-order-qty]")){state.order.lines[e.target.dataset.orderQty]=Math.max(0,Math.round((Number(e.target.value)||0)*10)/10);save();orders()}if(e.target.id==="delivery"){state.order.delivery=e.target.value;save()}if(e.target.matches("[data-grade]")){state.market.grades[e.target.dataset.grade]=e.target.value;save();market()}if(e.target.matches("[data-setting]")){item(e.target.dataset.setting)[e.target.dataset.key]=Math.max(0,Number(e.target.value)||0);save();settings()}if(e.target.id==="restoreFile"&&e.target.files?.[0])restore(e.target.files[0])});
