function selectMarketGrade(id,value){state.market.grades[id]=value;state.market.selected??={};state.market.selected[id]=state.market.period-1;save();const old=document.querySelector(`.market-card[data-market-id="${id}"]`);if(old)old.outerHTML=chart(item(id));const card=document.querySelector(`.market-card[data-market-id="${id}"]`);card?.querySelectorAll("[data-grade-value]").forEach(b=>b.classList.toggle("active",b.dataset.value===value));message(`${item(id).name} ${value}등급 시세를 표시합니다.`)}
// 새 품목과 기존 저장 데이터 모두 특등급을 기본값으로 사용한다.
function grade(id){return state.market.grades[id]||"특"}
// 등급 선택은 카드의 표시값과 선택 색상을 같은 순간에 갱신한다.
function setMarketGrade(id,value){state.market.grades[id]=value;state.market.selected??={};state.market.selected[id]=state.market.period-1;save();const target=document.querySelector(`.market-card[data-market-id="${id}"]`);if(target){target.outerHTML=chart(item(id));const updated=document.querySelector(`.market-card[data-market-id="${id}"]`);updated?.querySelectorAll("[data-grade-value]").forEach(b=>b.classList.toggle("active",b.dataset.value===value))}else market();message(`${item(id).name} ${value}등급 시세로 변경했어요.`);refreshLiveMarket(false,id)}
// API는 품목별로 모든 등급을 함께 돌려주므로, 등급 변경 시 선택 품목만 조회한다.
async function refreshLiveMarket(force=false,onlyId=null){if(marketLoading)return;const days=state.market.period,requests=[],items=onlyId?[item(onlyId)].filter(Boolean):orderItems();items.forEach(x=>Array.from({length:days},(_,i)=>{const date=apiDate(dateAt(i,days)),known=liveMarket[x.id]?.[date];if(force||!known||Date.now()-known.fetchedAt>216e5)requests.push({id:x.id,date})}));if(!requests.length){if(onlyId)renderMarketCard(onlyId);else market();return}marketLoading=true;marketProgress={done:0,total:requests.length};if(onlyId)renderMarketCard(onlyId);else market();const work=async r=>{try{const res=await fetch(`/api/market?item=${encodeURIComponent(r.id)}&date=${r.date}`),data=await res.json(),grades={};(data.resultData||[]).forEach(v=>{const g=String(v.G_NAME||"").trim();if(g)grades[g]={avg:numberPrice(v.AV_P),min:numberPrice(v.MI_P),max:numberPrice(v.MA_P),unit:String(v.U_NAME||"").trim(),name:String(v.PUM_NM||"").trim()}});liveMarket[r.id]??={};liveMarket[r.id][r.date]={fetchedAt:Date.now(),grades}}catch{liveMarket[r.id]??={};liveMarket[r.id][r.date]={fetchedAt:Date.now(),grades:{}}}finally{marketProgress.done++}};for(let i=0;i<requests.length;i+=4){await Promise.all(requests.slice(i,i+4).map(work));if(onlyId)renderMarketCard(onlyId);else market()}saveMarketCache();marketLoading=false;marketProgress={done:0,total:0};if(onlyId)renderMarketCard(onlyId);else market()}

/* 새로고침 중에는 이전/예시 시세를 그리지 않고, 로딩 전용 카드만 표시한다. */
function market(){state.market.selected??={};const status=marketLoading?`시세를 불러오는 중입니다. ${marketProgress.done}/${marketProgress.total}`:`마지막 시세 수집: ${marketFetchLabel()}`;const loadingCards=orderItems().map(x=>`<article class="card market-loading-card"><h3>${esc(x.name)}</h3><p>가락시장 시세를 불러오는 중…</p><div class="market-loading-graph" aria-label="${esc(x.name)} 시세 로딩 중"></div></article>`).join(""),cards=marketLoading?loadingCards:orderItems().map(chart).join("");$("#marketView").innerHTML=`<div class="section-head"><div><h2>가락시장 시세</h2><p>가락시장 도매시장 법인거래 기준</p></div><button class="secondary" id="refreshMarket" ${marketLoading?"disabled":""}>${marketLoading?"불러오는 중":"시세 새로고침"}</button></div><div class="period-switch"><button data-period="7" class="${state.market.period===7?"active":""}">최근 7일</button><button data-period="30" class="${state.market.period===30?"active":""}">최근 30일</button></div><p class="notice">${status}</p><section class="market-list">${cards}</section>`;if(!marketLoading)bindMarketGradeButtons();const autoKey=`${state.market.period}-${key(new Date())}`;if(!marketLoading&&marketAutoKey!==autoKey){marketAutoKey=autoKey;setTimeout(()=>refreshLiveMarket(),0)}}
const renderMarketWithEvent=market;market=function(...args){const result=renderMarketWithEvent(...args);window.dispatchEvent(new Event("veggi-market-rendered"));return result};

const FONT_SCALE_KEY="veggi-order-font-scale";
function fontScale(){return Number(localStorage.getItem(FONT_SCALE_KEY)||1)}
function applyFontScale(){document.documentElement.style.setProperty("--font-scale",String(fontScale()));document.body.style.zoom=String(fontScale())}
function setFontScale(value){localStorage.setItem(FONT_SCALE_KEY,String(value));applyFontScale();settings();message("글자 크기를 적용했어요.")}
function receiptRemaining(receipt,id){return Math.max(0,Number(receipt.lines?.[id]||0)-Number(receipt.returned?.[id]||0))}
function activeReceipts(){return(state.receipts||[]).filter(receipt=>Object.keys(receipt.lines||{}).some(id=>receiptRemaining(receipt,id)>0)).slice(0,3)}
function inventory(){const lows=state.items.filter(low),p=pending(),exp=state.items.filter(x=>x.expiry&&Math.ceil((new Date(`${x.expiry}T00:00:00`)-new Date())/864e5)<=2),closed=state.history.some(h=>h.type==="close"&&key(h.at)===today()),receipts=activeReceipts(),rows=state.items.map(x=>{const q=pendingQty(x.id);return `<div class="stock-row"><div class="stock-name"><span>${x.name}</span><small class="${low(x)?"low-stock":""}">${low(x)?`부족 · 기준 ${qty(x.threshold)}${x.unit}`:`기준 ${qty(x.threshold)}${x.unit}`}${q?` · <span class="inbound">입고 예정 +${qty(q)}${x.unit}</span>`:""}</small></div><div class="qty-control"><button data-stock-step="${x.id}" data-dir="-">−</button><input data-stock="${x.id}" inputmode="decimal" type="number" step="${step(x)}" value="${x.stock}"><button data-stock-step="${x.id}" data-dir="+">+</button></div><div class="quick-values"><button data-stock-value="${x.id}" data-value="0">0</button><button data-stock-value="${x.id}" data-value="${x.threshold}">${qty(x.threshold)}</button><button data-stock-value="${x.id}" data-value="${x.received}">${qty(x.received)}</button></div></div>`}).join(""),receiptPanel=receipts.length?`<section class="card inbound-panel receipt-panel"><strong>최근 입고 반영</strong>${receipts.map(receipt=>`<div><p>${receipt.kind==="auto"?"새벽 자동 입고":"입고 완료"} · ${Object.entries(receipt.lines).map(([id])=>`${esc(item(id)?.name||id)} ${qty(receiptRemaining(receipt,id))}${item(id)?.unit||""}`).join(" · ")}</p><button class="secondary" data-return-receipt="${receipt.id}">반품·입고 취소</button></div>`).join("")}</section>`:"";$("#inventoryView").innerHTML=`<div class="section-head"><div><h2>현재 재고</h2><p>수량을 바꾼 뒤 최종 확정하세요.</p></div></div><section class="summary-board"><article class="alert"><span>발주 필요</span><strong>${lows.length}개</strong></article><article><span>입고 예정</span><strong>${p.length}개</strong></article><article class="alert"><span>유통기한 임박</span><strong>${exp.length}개</strong></article></section>${p.length?`<section class="card inbound-panel"><strong>입고 예정 품목</strong><p>${p.map(([id,q])=>`${esc(item(id).name)} ${qty(q)}${item(id).unit}`).join(" · ")}</p><small>납품 예정일 ${state.order.delivery} · 자정 이후 앱을 열면 자동 입고 반영됩니다.</small></section>`:""}${receiptPanel}<section class="notice ${lows.length||exp.length?"warn":""}">${[lows.length?`재고 부족 ${lows.map(x=>x.name).join(", ")}`:"",exp.length?`유통기한 임박 ${exp.map(x=>x.name).join(", ")}`:""].filter(Boolean).join(" · ")||"현재 특이사항이 없습니다."}</section><section class="card stock-list">${rows}</section><div class="action-bar"><button class="secondary" id="commitStock">재고 최종 확정</button><button class="primary" id="dailyClose" ${closed?"disabled":""}>${closed?"오늘 마감 완료":"오늘 재고 마감"}</button></div>`}
function returnModal(receiptId){const receipt=(state.receipts||[]).find(x=>x.id===receiptId);if(!receipt)return;const rows=Object.keys(receipt.lines||{}).map(id=>{const x=item(id),remaining=receiptRemaining(receipt,id);return remaining?`<label class="return-row"><span><strong>${esc(x?.name||id)}</strong><small>취소 가능 ${qty(remaining)}${x?.unit||""}</small></span><input data-return-qty="${id}" type="number" min="0" max="${remaining}" step="${step(x||{unit:""})}" value="0"></label>`:""}).join("");$("#modalRoot").innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-top"><div><h3>반품·입고 취소</h3><p class="history-help">반품 수량만 입력하세요. 재고에서 같은 수량을 차감합니다.</p></div><button class="close" data-close-modal>×</button></div><div class="return-list">${rows||"<p class=\"history-help\">취소할 수량이 없습니다.</p>"}</div><button class="primary return-confirm" data-confirm-return="${receipt.id}">입고 취소 반영</button></section></div>`}
function confirmReturn(receiptId){const receipt=(state.receipts||[]).find(x=>x.id===receiptId);if(!receipt)return;let changed=0;document.querySelectorAll("[data-return-qty]").forEach(input=>{const id=input.dataset.returnQty,x=item(id),amount=Math.min(receiptRemaining(receipt,id),Math.max(0,Math.round((Number(input.value)||0)*10)/10));if(!amount||!x)return;x.stock=Math.max(0,(Number(x.stock)||0)-amount);x.updatedAt=new Date().toISOString();receipt.returned??={};receipt.returned[id]=(Number(receipt.returned[id])||0)+amount;log("return",x,`반품 · 입고 취소 -${qty(amount)}${x.unit}`);changed++});if(!changed)return message("반품 수량을 입력해 주세요.");save();$("#modalRoot").innerHTML="";render();message("반품 수량을 재고에서 취소했어요.")}
function eventLabel(h){return h.type==="order"?"발주":h.type==="received"?"입고":h.type==="return"?"반품":h.type==="stock"?"재고":h.type==="close"?"마감":"기록"}
function historyModal(k){const ev=state.history.filter(h=>key(h.at)===k);$("#modalRoot").innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-top"><div><h3>${k} 기록</h3><p class="history-help">${ev.length}건 · 삭제해도 재고 수량은 바뀌지 않습니다.</p></div><button class="close" data-close-modal>×</button></div>${ev.length?ev.map(h=>`<article class="event-row"><time>${new Date(h.at).toLocaleTimeString("ko-KR",{hour:"2-digit",minute:"2-digit"})} · ${eventLabel(h)}</time><strong>${esc(h.itemName)}</strong> · ${esc(h.text)}<button class="history-delete" data-delete-history="${h.id}">기록 삭제</button></article>`).join(""):'<p class="history-help">이 날짜의 기록이 없습니다.</p>'}</section></div>`}
function deleteHistory(id){state.history=state.history.filter(entry=>entry.id!==id);save();const openTitle=$("#modalRoot h3")?.textContent||"";const date=openTitle.match(/^\d{4}-\d{2}-\d{2}/)?.[0];if(date)historyModal(date);calendar();message("기록을 삭제했어요.")}
function settings(){const scales=[[.9,"작게"],[1,"기본"],[1.15,"크게"],[1.3,"아주 크게"]];if(settingsPage==="menu"){$("#settingsView").innerHTML=`<div class="section-head"><div><h2>설정</h2><p>설정할 항목을 선택하세요.</p></div></div><section class="setting-menu"><button data-settings-page="font"><span><strong>글자 크기</strong><small>휴대폰 화면에 맞게 조절합니다.</small></span><b>›</b></button><button data-settings-page="items"><span><strong>품목·발주 설정</strong><small>기준재고, 기본 발주량, 단가를 수정합니다.</small></span><b>›</b></button><button data-settings-page="backup"><span><strong>데이터 백업·복원</strong><small>재고·발주·이력·설정을 파일로 보관합니다.</small></span><b>›</b></button></section>`;return}if(settingsPage==="font"){$("#settingsView").innerHTML=`<div class="section-head"><div><h2>글자 크기</h2><p>이 기기에서만 적용됩니다.</p></div><button class="secondary" data-settings-page="menu">뒤로</button></div><section class="card font-size-card"><strong>화면 글자 크기</strong><p>버튼과 입력창도 함께 보기 편하게 조절됩니다.</p><div class="font-size-options">${scales.map(([value,label])=>`<button data-font-scale="${value}" class="${fontScale()===value?"active":""}">${label}</button>`).join("")}</div></section>`;return}if(settingsPage==="items"){$("#settingsView").innerHTML=`<div class="section-head"><div><h2>품목·발주 설정</h2><p>기준재고와 기본 발주량을 수정합니다.</p></div><button class="secondary" data-settings-page="menu">뒤로</button></div><section class="card setting-list">${state.items.map(x=>`<div class="setting-row"><div><h3>${x.name}</h3><p>기준 ${qty(x.threshold)}${x.unit} · 기본 발주 ${qty(x.orderAmount)}${x.unit}</p></div><input data-setting="${x.id}" data-key="orderAmount" type="number" step="${step(x)}" value="${x.orderAmount}"></div>`).join("")}</section>`;return}$("#settingsView").innerHTML=`<div class="section-head"><div><h2>데이터 백업·복원</h2><p>복원하면 이 기기의 현재 데이터가 바뀝니다.</p></div><button class="secondary" data-settings-page="menu">뒤로</button></div><section class="card inbound-panel"><strong>안전하게 보관하세요</strong><p>재고, 발주, 이력, 품목 설정을 JSON 파일로 저장합니다.</p><div class="backup-actions"><button class="secondary" id="backup">백업 저장</button><button class="primary" id="restore">복원하기</button></div><input id="restoreFile" type="file" accept="application/json" hidden></section>`}
document.addEventListener("input",event=>{const input=event.target;if(!input.matches?.("[data-order-qty]"))return;state.order.lines[input.dataset.orderQty]=Math.max(0,Math.round((Number(input.value)||0)*10)/10);save();const total=orderLines().length;document.querySelectorAll("[data-order-count]").forEach(node=>node.textContent=`${total}개`);document.querySelectorAll("[data-order-total]").forEach(node=>node.textContent=`${total}개 품목`)});
document.addEventListener("click",event=>{const button=event.target.closest("button");if(!button)return;if(button.dataset.returnReceipt)return returnModal(button.dataset.returnReceipt);if(button.dataset.confirmReturn)return confirmReturn(button.dataset.confirmReturn);if(button.dataset.deleteHistory)return deleteHistory(button.dataset.deleteHistory);if(button.dataset.fontScale)return setFontScale(Number(button.dataset.fontScale))});
function restore(f){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data.items))throw 0;state={items:normalize(data.items),history:data.history||[],receipts:data.receipts||[],order:data.order||data.orderDraft||{stage:"ready",delivery:key(Date.now()+864e5),lines:{}},market:{period:data.market?.period||data.market?.range||7,order:(data.market?.order||base.filter(x=>!['rice','egg'].includes(x.id)).map(x=>x.id)).filter(id=>!['rice','egg'].includes(id)),grades:data.market?.grades||{}},draftBefore:{}};autoReceiveDueOrders();save();render();message("백업을 복원했어요.")}catch{message("올바른 백업 파일이 아닙니다.")}};reader.readAsText(f)}
autoReceiveDueOrders();applyFontScale();render();

/* 2026-09-24: 확대 글꼴과 입고 취소·단위 UX 보완 */
/* var로 선언해 초기 화면의 글자 크기 적용보다 먼저 안전하게 참조되도록 한다. */
var TOOLTIP_SCALE_KEY="veggi-order-tooltip-scale";
function tooltipScale(){return Number(localStorage.getItem(TOOLTIP_SCALE_KEY)||1)}
function applyFontScale(){document.documentElement.style.setProperty("--font-scale",String(fontScale()));document.documentElement.style.setProperty("--tooltip-font-scale",String(tooltipScale()));document.body.style.zoom=String(fontScale())}
function setTooltipScale(value){localStorage.setItem(TOOLTIP_SCALE_KEY,String(value));applyFontScale();settings();market();message("그래프 정보 글자 크기를 적용했어요.")}
function decimal(value,divisor){return value===""?"":Math.round((Number(value)||0)/divisor*10)/10}
function migrateOperatingUnits(data){
  const rice=data.items?.find(x=>x.id==="rice"), egg=data.items?.find(x=>x.id==="egg");
  const convertLines=(lines,id,divisor)=>{if(lines&&lines[id]!==undefined)lines[id]=decimal(lines[id],divisor)};
  const convertReceipts=(id,divisor)=>data.receipts?.forEach(receipt=>{convertLines(receipt.lines,id,divisor);convertLines(receipt.returned,id,divisor)});
  const multiply=(value,factor)=>value===""?"":Math.round((Number(value)||0)*factor*10)/10;
  const multiplyLines=(lines,id,factor)=>{if(lines&&lines[id]!==undefined)lines[id]=multiply(lines[id],factor)};
  const multiplyReceipts=(id,factor)=>data.receipts?.forEach(receipt=>{multiplyLines(receipt.lines,id,factor);multiplyLines(receipt.returned,id,factor)});
  if(rice && String(rice.unit).includes("10kg")){
    rice.stock=multiply(rice.stock,10);multiplyLines(data.order?.lines,"rice",10);multiplyReceipts("rice",10);
  }
  if(rice){rice.unit="kg";rice.received=20;rice.threshold=10;rice.orderAmount=20;}
  if(egg?.unit==="개"){
    egg.stock=decimal(egg.stock,30);egg.unit="판";egg.received=1;egg.threshold=1;egg.orderAmount=1;
    convertLines(data.order?.lines,"egg",30);convertReceipts("egg",30);
  }
  if(egg){egg.unit="판";egg.received=4;egg.threshold=1;egg.orderAmount=4;}
  return data;
}
function orders(){
  state.items.forEach(x=>state.order.lines[x.id]??=0);
  const rows=state.items.map(x=>{
    const twice=Math.round(x.orderAmount*20)/10;
    return `<div class="order-row"><div><h3>${x.name}</h3><p>기본 ${qty(x.orderAmount)}${x.unit}${x.spec?` / ${x.spec}`:""}</p></div><input data-order-qty="${x.id}" type="number" min="0" step="${step(x)}" inputmode="decimal" value="${qty(state.order.lines[x.id]||0)}"><div class="quick-values order-slots"><button data-order-value="${x.id}" data-value="0">0</button><button data-order-value="${x.id}" data-value="${x.orderAmount}">${qty(x.orderAmount)}</button><button data-order-value="${x.id}" data-value="${twice}">${qty(twice)}</button></div></div>`;
  }).join(""), total=orderLines().length;
  $("#ordersView").innerHTML=`<div class="section-head"><div><h2>오늘 발주</h2><p>수량이 0보다 큰 품목만 발주합니다.</p></div></div><section class="card order-tools"><label>입고 예정일<input id="delivery" type="date" value="${state.order.delivery}"></label><label>발주 품목<strong data-order-count>${total}개</strong></label></section><section class="card order-list">${rows}</section><section class="card order-total"><span>발주 예정</span><strong data-order-total>${total}개 품목</strong></section><div class="action-bar"><button class="primary" id="orderAction">${state.order.stage==="sent"?"입고 완료 처리":"발주 전송"}</button></div>`;
}
function returnModal(receiptId){
  const receipt=(state.receipts||[]).find(x=>x.id===receiptId);if(!receipt)return;
  const rows=Object.keys(receipt.lines||{}).map(id=>{
    const x=item(id),remaining=receiptRemaining(receipt,id),half=Math.round(remaining/2*10)/10;
    return remaining?`<div class="return-row"><span><strong>${esc(x?.name||id)}</strong><small>취소 가능 ${qty(remaining)}${x?.unit||""}</small></span><div class="return-control"><div class="quick-values return-slots"><button type="button" data-return-value="${id}" data-value="0">0</button><button type="button" data-return-value="${id}" data-value="${half}">${qty(half)}</button><button type="button" data-return-value="${id}" data-value="${remaining}">${qty(remaining)}</button></div><input data-return-qty="${id}" type="number" min="0" max="${remaining}" step="${step(x||{unit:""})}" value="0"></div></div>`:"";
  }).join("");
  $("#modalRoot").innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-top"><div><h3>반품·입고 취소</h3><p class="history-help">반품 수량만 입력하세요. 재고에서 같은 수량을 차감합니다.</p></div><button class="close" data-close-modal>×</button></div><div class="return-list">${rows||"<p class=\"history-help\">취소할 수량이 없습니다.</p>"}</div><button class="primary return-confirm" data-confirm-return="${receipt.id}">입고 취소 반영</button></section></div>`;
}
function settings(){
  const scales=[[.9,"작게"],[1,"기본"],[1.15,"크게"],[1.3,"아주 크게"]];
  if(settingsPage==="menu"){$("#settingsView").innerHTML=`<div class="section-head"><div><h2>설정</h2><p>설정할 항목을 선택하세요.</p></div></div><section class="setting-menu"><button data-settings-page="font"><span><strong>글자 크기</strong><small>화면과 그래프 정보를 보기 좋게 조절합니다.</small></span><b>›</b></button><button data-settings-page="items"><span><strong>품목·발주 설정</strong><small>기준재고, 기본 발주량, 단가를 수정합니다.</small></span><b>›</b></button><button data-settings-page="backup"><span><strong>데이터 백업·복원</strong><small>재고·발주·이력·설정을 파일로 보관합니다.</small></span><b>›</b></button></section>`;return}
  if(settingsPage==="font"){$("#settingsView").innerHTML=`<div class="section-head"><div><h2>글자 크기</h2><p>이 기기에서만 적용됩니다.</p></div><button class="secondary" data-settings-page="menu">뒤로</button></div><section class="card font-size-card"><strong>화면 글자 크기</strong><p>버튼과 입력창을 포함한 일반 화면 크기입니다.</p><div class="font-size-options">${scales.map(([value,label])=>`<button data-font-scale="${value}" class="${fontScale()===value?"active":""}">${label}</button>`).join("")}</div><strong class="tooltip-setting-title">그래프 정보 글자 크기</strong><p>그래프를 눌렀을 때 뜨는 날짜·가격·등급 비교 정보 크기입니다.</p><div class="font-size-options">${scales.map(([value,label])=>`<button data-tooltip-scale="${value}" class="${tooltipScale()===value?"active":""}">${label}</button>`).join("")}</div></section>`;return}
  if(settingsPage==="items"){$("#settingsView").innerHTML=`<div class="section-head"><div><h2>품목·발주 설정</h2><p>기준재고와 기본 발주량을 수정합니다.</p></div><button class="secondary" data-settings-page="menu">뒤로</button></div><section class="card setting-list">${state.items.map(x=>`<div class="setting-row"><div><h3>${x.name}</h3><p>기준 ${qty(x.threshold)}${x.unit} · 기본 발주 ${qty(x.orderAmount)}${x.unit}</p></div><input data-setting="${x.id}" data-key="orderAmount" type="number" step="${step(x)}" value="${x.orderAmount}"></div>`).join("")}</section>`;return}
  $("#settingsView").innerHTML=`<div class="section-head"><div><h2>데이터 백업·복원</h2><p>복원하면 이 기기의 현재 데이터가 바뀝니다.</p></div><button class="secondary" data-settings-page="menu">뒤로</button></div><section class="card inbound-panel"><strong>안전하게 보관하세요</strong><p>재고, 발주, 이력, 품목 설정을 JSON 파일로 저장합니다.</p><div class="backup-actions"><button class="secondary" id="backup">백업 저장</button><button class="primary" id="restore">복원하기</button></div><input id="restoreFile" type="file" accept="application/json" hidden></section>`;
}
document.addEventListener("click",event=>{const button=event.target.closest("[data-return-value]");if(!button)return;const input=document.querySelector(`[data-return-qty="${button.dataset.returnValue}"]`);if(input)input.value=button.dataset.value});
document.addEventListener("click",event=>{const button=event.target.closest("[data-tooltip-scale]");if(button)setTooltipScale(Number(button.dataset.tooltipScale))});
function restore(f){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data.items))throw 0;state=migrateOperatingUnits({items:normalize(data.items),history:data.history||[],receipts:data.receipts||[],order:data.order||data.orderDraft||{stage:"ready",delivery:key(Date.now()+864e5),lines:{}},market:{period:data.market?.period||data.market?.range||7,order:(data.market?.order||base.filter(x=>!["rice","egg"].includes(x.id)).map(x=>x.id)).filter(id=>!["rice","egg"].includes(id)),grades:data.market?.grades||{}},draftBefore:{}});autoReceiveDueOrders();save();render();message("백업을 복원했어요.")}catch{message("올바른 백업 파일이 아닙니다.")}};reader.readAsText(f)}
state=migrateOperatingUnits(state);save();applyFontScale();render();

/* 글자 크기 메뉴는 한 번의 전역 클릭 처리만 사용한다. 이전 누적 리스너와
   재렌더링이 겹쳐 설정 화면이 멈추던 경로를 차단한다. */
function setFontScale(value){
  const scale=[.9,1,1.15,1.3].includes(value)?value:1;
  localStorage.setItem(FONT_SCALE_KEY,String(scale));
  applyFontScale();
  settings();
  message("글자 크기를 적용했어요.");
}
document.addEventListener("click",event=>{
  const pageButton=event.target.closest("[data-settings-page]");
  if(!pageButton)return;
  event.preventDefault();event.stopImmediatePropagation();
  settingsPage=pageButton.dataset.settingsPage||"menu";
  settings();
},true);
document.addEventListener("click",event=>{
  const button=event.target.closest("[data-font-scale]");
  if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  setFontScale(Number(button.dataset.fontScale));
},true);
document.addEventListener("click",event=>{
  const button=event.target.closest("[data-tooltip-scale]");
  if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  setTooltipScale(Number(button.dataset.tooltipScale));
},true);

/* 계란은 실사용 단위에 맞춰 0·2·4판을 빠르게 입력한다. */
function inventory(){
  const lows=state.items.filter(low),p=pending(),exp=state.items.filter(x=>x.expiry&&Math.ceil((new Date(`${x.expiry}T00:00:00`)-new Date())/864e5)<=2),closed=state.history.some(h=>h.type==="close"&&key(h.at)===today()),receipts=activeReceipts();
  const rows=state.items.map(x=>{const q=pendingQty(x.id),quick=x.id==="egg"?[0,2,4]:[0,x.threshold,x.received];return `<div class="stock-row"><div class="stock-name"><span>${x.name}</span><small class="${low(x)?"low-stock":""}">${low(x)?`부족 · 기준 ${qty(x.threshold)}${x.unit}`:`기준 ${qty(x.threshold)}${x.unit}`}${q?` · <span class="inbound">입고 예정 +${qty(q)}${x.unit}</span>`:""}</small></div><div class="qty-control"><button data-stock-step="${x.id}" data-dir="-">−</button><input data-stock="${x.id}" inputmode="decimal" type="number" step="${step(x)}" value="${x.stock}"><button data-stock-step="${x.id}" data-dir="+">+</button></div><div class="quick-values">${quick.map(value=>`<button data-stock-value="${x.id}" data-value="${value}">${qty(value)}</button>`).join("")}</div></div>`}).join("");
  const receiptPanel=receipts.length?`<section class="card inbound-panel receipt-panel"><strong>최근 입고 반영</strong>${receipts.map(receipt=>`<div><p>${receipt.kind==="auto"?"새벽 자동 입고":"입고 완료"} · ${Object.entries(receipt.lines).map(([id])=>`${esc(item(id)?.name||id)} ${qty(receiptRemaining(receipt,id))}${item(id)?.unit||""}`).join(" · ")}</p><button class="secondary" data-return-receipt="${receipt.id}">반품·입고 취소</button></div>`).join("")}</section>`:"";
  $("#inventoryView").innerHTML=`<div class="section-head"><div><h2>현재 재고</h2><p>수량을 바꾼 뒤 최종 확정하세요.</p></div></div><section class="summary-board"><article class="alert"><span>발주 필요</span><strong>${lows.length}개</strong></article><article><span>입고 예정</span><strong>${p.length}개</strong></article><article class="alert"><span>유통기한 임박</span><strong>${exp.length}개</strong></article></section>${p.length?`<section class="card inbound-panel"><strong>입고 예정 품목</strong><p>${p.map(([id,q])=>`${esc(item(id).name)} ${qty(q)}${item(id).unit}`).join(" · ")}</p><small>납품 예정일 ${state.order.delivery} · 자정 이후 앱을 열면 자동 입고 반영됩니다.</small></section>`:""}${receiptPanel}<section class="notice ${lows.length||exp.length?"warn":""}">${[lows.length?`재고 부족 ${lows.map(x=>x.name).join(", ")}`:"",exp.length?`유통기한 임박 ${exp.map(x=>x.name).join(", ")}`:""].filter(Boolean).join(" · ")||"현재 특이사항이 없습니다."}</section><section class="card stock-list">${rows}</section><div class="action-bar"><button class="secondary" id="commitStock">재고 최종 확정</button><button class="primary" id="dailyClose" ${closed?"disabled":""}>${closed?"오늘 마감 완료":"오늘 재고 마감"}</button></div>`;
}

/* 재고 화면은 일수로 입력하고, 저장·발주 계산에는 실제 수량을 계속 사용한다. */
function stockPerDay(x){return Number(x.received||0)/Math.max(1,Number(x.cycle||1))}
function daysFromStock(x){return x.stock===""?"":Math.max(0,Math.round((Number(x.stock)||0)/stockPerDay(x)*10)/10)}
function stockFromDays(x,days){return Math.max(0,Math.round((Number(days)||0)*stockPerDay(x)*10)/10)}
function inventory(){
  const lows=state.items.filter(low),p=pending(),exp=state.items.filter(x=>x.expiry&&Math.ceil((new Date(`${x.expiry}T00:00:00`)-new Date())/864e5)<=2),closed=state.history.some(h=>h.type==="close"&&key(h.at)===today()),receipts=activeReceipts();
  const rows=state.items.map(x=>{const inbound=pendingQty(x.id),days=daysFromStock(x),thresholdDays=Math.round(Number(x.threshold)/stockPerDay(x)*10)/10,quick=x.id==="egg"?[0,2,4]:[0,Math.max(1,Math.round(x.cycle/2)),x.cycle],stockText=x.stock===""?"수량 미입력":`재고 ${qty(x.stock)}${x.unit} · 약 ${qty(days)}일치`;return `<div class="stock-row"><div class="stock-name"><span>${x.name}</span><small class="${low(x)?"low-stock":""}">${low(x)?`부족 · ${stockText}`:stockText} · 기준 약 ${qty(thresholdDays)}일${inbound?` · <span class="inbound">입고 예정 +${qty(inbound)}${x.unit}</span>`:""}</small></div><div class="qty-control"><button data-stock-day-step="${x.id}" data-dir="-">−</button><input data-stock-days="${x.id}" aria-label="${x.name} 남은 일수" inputmode="decimal" type="number" min="0" step="1" placeholder="일수" value="${days}"><button data-stock-day-step="${x.id}" data-dir="+">+</button></div><div class="quick-values">${quick.map(value=>`<button data-stock-days-value="${x.id}" data-value="${value}">${qty(value)}일</button>`).join("")}</div></div>`}).join("");
  const receiptPanel=receipts.length?`<section class="card inbound-panel receipt-panel"><strong>최근 입고 반영</strong>${receipts.map(receipt=>`<div><p>${receipt.kind==="auto"?"새벽 자동 입고":"입고 완료"} · ${Object.entries(receipt.lines).map(([id])=>`${esc(item(id)?.name||id)} ${qty(receiptRemaining(receipt,id))}${item(id)?.unit||""}`).join(" · ")}</p><button class="secondary" data-return-receipt="${receipt.id}">반품·입고 취소</button></div>`).join("")}</section>`:"";
  $("#inventoryView").innerHTML=`<div class="section-head"><div><h2>현재 재고</h2><p>남은 일수를 입력하면 실제 수량으로 환산됩니다.</p></div></div><section class="summary-board"><article class="alert"><span>발주 필요</span><strong>${lows.length}개</strong></article><article><span>입고 예정</span><strong>${p.length}개</strong></article><article class="alert"><span>유통기한 임박</span><strong>${exp.length}개</strong></article></section>${p.length?`<section class="card inbound-panel"><strong>입고 예정 품목</strong><p>${p.map(([id,q])=>`${esc(item(id).name)} ${qty(q)}${item(id).unit}`).join(" · ")}</p><small>납품 예정일 ${state.order.delivery} · 자정 이후 앱을 열면 자동 입고 반영됩니다.</small></section>`:""}${receiptPanel}<section class="notice ${lows.length||exp.length?"warn":""}">${[lows.length?`재고 부족 ${lows.map(x=>x.name).join(", ")}`:"",exp.length?`유통기한 임박 ${exp.map(x=>x.name).join(", ")}`:""].filter(Boolean).join(" · ")||"현재 특이사항이 없습니다."}</section><section class="card stock-list">${rows}</section><div class="action-bar"><button class="secondary" id="commitStock">재고 최종 확정</button><button class="primary" id="dailyClose" ${closed?"disabled":""}>${closed?"오늘 마감 완료":"오늘 재고 마감"}</button></div>`;
}
document.addEventListener("click",event=>{
  const button=event.target.closest("[data-stock-day-step],[data-stock-days-value]");if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  const id=button.dataset.stockDayStep||button.dataset.stockDaysValue,x=item(id),days=button.dataset.stockDaysValue!==undefined?Number(button.dataset.value):Number(daysFromStock(x)||0)+(button.dataset.dir==="+"?1:-1);
  setStock(id,stockFromDays(x,days));
},true);
document.addEventListener("change",event=>{
  const input=event.target.closest("[data-stock-days]");if(!input)return;
  event.stopImmediatePropagation();
  const x=item(input.dataset.stockDays);setStock(x.id,stockFromDays(x,input.value));
},true);
